import {copy,equal,diffLayouts,mergePatch} from './sync-protocol.js';
export class SharedSync{
constructor({url,read,apply,status,conflict,busy=()=>false,fetcher=fetch,storage=globalThis.localStorage}){Object.assign(this,{url,read,apply,status,conflict,busy,fetcher,storage});this.ready=false;this.running=false;this.revision=0;this.base=null;this.timer=null;this.interval=null;this.draftKey='qiju-shared-pending-v1'}
statusText(text){this.status(text,this.revision)}
async request(path,options={}){const response=await this.fetcher(this.url+path,{...options,cache:'no-store',credentials:'omit',signal:AbortSignal.timeout(12000)});let data;try{data=await response.json()}catch{throw Error('共享服务返回异常')}if(!response.ok&&response.status!==409)throw Error(data.error||'共享服务暂不可用');if(!data.layout||!Number.isSafeInteger(data.revision)||!Array.isArray(data.layout.items)||!Array.isArray(data.layout.decorations))throw Error('共享布局格式错误');return {data,conflict:response.status===409}}
cache(){if(!this.base)return;try{const current=this.read();if(equal(this.base,current))this.storage.removeItem(this.draftKey);else this.storage.setItem(this.draftKey,JSON.stringify({base:this.base,layout:current}))}catch{this.statusText('本机备份不可用，请导出未同步布局')}}
async start(){if(this.running)return false;this.running=true;this.statusText('正在连接共享布局…');try{const {data}=await this.request('/api/layout');this.base=copy(data.layout);this.revision=data.revision;let layout=data.layout,draft;try{draft=JSON.parse(this.storage.getItem(this.draftKey)||'null')}catch{}if(draft?.base&&draft?.layout){const result=mergePatch(layout,diffLayouts(draft.base,draft.layout));layout=result.layout;if(result.conflicts.length)this.conflict(draft.layout,result.conflicts.length)}this.apply(copy(layout),true);this.ready=true;this.statusText('共享布局已连接');this.changed();return true}catch(e){this.statusText('共享服务离线，点击重连');return false}finally{this.running=false;if(!this.interval)this.interval=setInterval(()=>this.tick(),3000)}}
changed(){if(!this.ready)return;this.cache();if(!equal(this.base,this.read())){this.statusText('正在同步修改…');clearTimeout(this.timer);this.timer=setTimeout(()=>this.tick(),300)}}
async tick(){if(this.running||this.busy())return;if(!this.ready)return this.start();this.running=true;try{const sent=copy(this.read()),ops=diffLayouts(this.base,sent);if(ops.length){const {data,conflict}=await this.request('/api/layout',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({requestId:crypto.randomUUID(),ops})});const current=copy(this.read());const remaining=conflict?diffLayouts(this.base,current):diffLayouts(sent,current);const result=mergePatch(data.layout,remaining);if(result.conflicts.length)this.conflict(current,result.conflicts.length);this.base=copy(data.layout);this.revision=data.revision;if(!equal(result.layout,current))this.apply(result.layout,true);this.cache();this.statusText(result.conflicts.length?'存在修改冲突，草稿已保留':equal(this.base,this.read())?'已同步 · 所有人共享':'正在同步后续修改…')}else{const {data}=await this.request('/api/layout');const current=copy(this.read());const during=diffLayouts(this.base,current),result=mergePatch(data.layout,during);if(result.conflicts.length)this.conflict(current,result.conflicts.length);const external=!equal(this.base,data.layout);this.base=copy(data.layout);this.revision=data.revision;if(!equal(result.layout,current))this.apply(result.layout,external);this.cache();this.statusText(equal(this.base,this.read())?'已同步 · 所有人共享':'正在同步修改…')}}catch(e){this.cache();this.statusText('离线：修改暂存本机，自动重试')}finally{this.running=false}}
stop(){clearTimeout(this.timer);clearInterval(this.interval);this.interval=null}
}
